// Swagger UI bootstrap. The OpenAPI spec itself is auto-generated by
// `app.doc31('/api/openapi.json', ...)` in app.ts — every `app.openapi(...)`
// route contributes its own Zod request/response schemas. There is no
// hand-rolled spec to drift from the actual handlers.

const SWAGGER_HTML = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Open Brain API</title>
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5.17.14/swagger-ui.css" />
  <style>body { margin: 0; }</style>
</head>
<body>
  <div id="swagger-ui"></div>
  <script src="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5.17.14/swagger-ui-bundle.js"></script>
  <script>
    // Carry the auth key from the URL (?key=...) into both the openapi.json
    // fetch AND every "Try it out" request the UI fires. Lets the docs page
    // stay operable behind Bearer auth without re-authorizing each reload.
    const params = new URLSearchParams(window.location.search);
    const key = params.get('key') || '';
    const specUrl = '/api/openapi.json' + (key ? '?key=' + encodeURIComponent(key) : '');

    window.onload = () => {
      window.ui = SwaggerUIBundle({
        url: specUrl,
        dom_id: '#swagger-ui',
        deepLinking: true,
        presets: [SwaggerUIBundle.presets.apis],
        requestInterceptor: (req) => {
          if (key) {
            req.headers['Authorization'] = 'Bearer ' + key;
          }
          return req;
        },
      });
    };
  </script>
</body>
</html>`;

export function swaggerUiHandler(): Response {
  return new Response(SWAGGER_HTML, {
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  });
}
